from construire import Chapter,fig,box,qs,sub
from figures_communes import common,plot
from math import exp,log,sqrt

def create():
 c=Chapter(3,'Circuits linéaires du premier ordre','1.3','les régimes libres et les réponses à un échelon des circuits RC et RL, leurs bilans énergétiques et leur simulation numérique.')
 common(c)
 plot(c,'charge',[('1-exp(-x)','Charge','otNavy'),('exp(-x)','Décharge','otGreenDark')],ymin=0,ymax=1.12,ylabel='$u_C/E$')
 plot(c,'courants',[('exp(-x)','$i_{RC}/(E/R)$','otNavy'),('1-exp(-x)','$i_{RL}/(E/R)$','otGreenDark')],ymin=0,ymax=1.12,ylabel='Courant réduit')
 plot(c,'energie',[('(1-exp(-x))^2',r'$\mathcal E_C/(CE^2/2)$','otNavy'),('1-exp(-2*x)','$W_J/(CE^2/2)$','otOrange')],ymin=0,ymax=1.12,ylabel='Énergie réduite')
 c.intro="Un interrupteur change le circuit en un instant, mais toutes les grandeurs ne sautent pas pour autant. Le condensateur conserve sa tension et la bobine son courant. Ces propriétés permettent de prévoir l’évolution avant même de résoudre l’équation."
 c.mapping=r"Établir une équation du premier ordre dans un circuit à une ou deux mailles ; fixer la condition initiale ; distinguer transitoire et permanent.\par Résoudre un régime libre ou une excitation en échelon ; estimer sa durée ; conduire un bilan d’énergie.\par Acquérir un transitoire et mettre en œuvre Euler pour une excitation quelconque."
 c.prereq=r"Lois des nœuds et des mailles ; modèle de Thévenin ; $i_C=C\dot u_C$ ; $u_L=L\dot i_L$ ; dérivée de l’exponentielle. Le chapitre 02 fournit les orientations et les lois locales."
 c.method="Dessiner les états avant et après commutation ; déterminer la grandeur continue ; trouver le régime final ; établir l’équation ; résoudre ; vérifier condition initiale, dérivée et limite."
 c.boundary="Pages internes 14 et 15 (pages PDF 51 et 52). Les circuits du deuxième ordre sont étudiés aux chapitres 04 et 05."
 c.diagnostic=qs(r"Calculer $RC$ pour $R=10$ k$\Omega$, $C=100$ nF ; $L/R$ pour $L=20$ mH, $R=100\ \Omega$.",r"Dériver $u(t)=3+2e^{-t/\tau}$.",r"Quelle grandeur est continue dans un condensateur ? Dans une bobine ? Préciser l’hypothèse physique.",r"Que valent $u_C$ et $i$ en régime final pour un RC série alimenté par une source idéale $E$ ?",r"Résoudre $\dot y+y/\tau=0$ avec $y(0)=y_0$.",r"Combien vaut $e^{-1}$ approximativement ? $e^{-5}$ ?",r"Donner l’énergie d’un condensateur de $1\ \mathrm{\mu F}$ sous $10$ V.",r"Un temps caractéristique est-il la durée exacte au bout de laquelle le transitoire est terminé ?")
 c.diag_sol=sub('D1 et D2',r"$RC=1$ ms ; $L/R=0{,}20$ ms. $\dot u=-(2/\tau)e^{-t/\tau}$. L’exposant $t/\tau$ est sans dimension.")+sub('D3 à D5',r"Pour des excitations non impulsionnelles : continuité de $u_C$ si le courant reste fini, de $i_L$ si la tension reste finie. En régime permanent continu du RC série, $i=0$ et $u_C=E$. La solution libre est $y=y_0e^{-t/\tau}$.")+sub('D6 à D8',r"$e^{-1}\simeq0{,}368$ et $e^{-5}\simeq0{,}00674$. L’énergie vaut $50\ \mathrm{\mu J}$. L’exponentielle n’atteint sa limite qu’asymptotiquement ; la durée pratique dépend du seuil de précision choisi.")
 c.c('Une commutation, trois instants',r'''On distingue $0^-$ (juste avant), $0^+$ (juste après) et $+\infty$ (régime final). Le schéma de $0^-$ fixe l’état initial ; celui de $0^+$ fixe l’équation de l’évolution qui suit.
'''+fig('rc','Après la commutation, le condensateur est relié à e(t) par R ; uC est la grandeur d’état.')+box('loi','Une réserve d’énergie ne change pas brutalement',r"$u_C(0^+)=u_C(0^-)$ si le courant n’est pas impulsionnel ; $i_L(0^+)=i_L(0^-)$ si la tension n’est pas impulsionnelle. Ces continuités ne concernent pas nécessairement $i_C$ ou $u_L$.")+sub('Exemple RC',r"Un condensateur initialement déchargé reçoit un échelon $e(t)=E$ pour $t>0$. À $0^+$, $u_C=0$ donc la résistance reçoit $E$ et $i=E/R$. À long terme, $i=0$ et $u_C=E$. La valeur finale ne doit pas être utilisée comme valeur initiale.")+box('methode','Avant de calculer',"Écrire un petit tableau : état avant, grandeur continue, état juste après, état final. Cette anticipation fournit quatre contrôles de la solution."))
 c.c('La réponse universelle du premier ordre',box('loi','Forme canonique et solution',r"Pour $\tau>0$, $\tau\dot s+s=s_\infty$ et $s(0^+)=s_0$ donnent $\result{s(t)=s_\infty+(s_0-s_\infty)e^{-t/\tau}}$. La constante $s_\infty$ est ici la réponse permanente à une excitation constante.")+sub('Démonstration',r"La solution particulière constante vaut $s_\infty$. La différence $z=s-s_\infty$ vérifie $\dot z=-z/\tau$, donc $z=Ae^{-t/\tau}$. La condition initiale impose $A=s_0-s_\infty$. La dérivée initiale est $(s_\infty-s_0)/\tau$.")+fig('charge','Charge et décharge ont le même temps caractéristique ; elles ne possèdent pas la même limite.')+box('piege','Le forçage doit être constant sur l’intervalle',r"La formule avec $s_\infty$ constant ne s’applique pas directement à une entrée variable quelconque. Pour un créneau, résoudre par morceaux ; pour une autre entrée, intégrer l’équation ou la simuler."))
 c.c('Le circuit RC soumis à un échelon',fig('rc','La loi des mailles et la convention récepteur donnent E = Ri + uC et i = C duC/dt.')+box('loi','Équation et réponse',r"$RC\dot u_C+u_C=E$ ; $\tau=RC$. Avec $u_C(0)=U_0$ : $u_C=E+(U_0-E)e^{-t/\tau}$, $i=(E-U_0)e^{-t/\tau}/R$ et $u_R=(E-U_0)e^{-t/\tau}$.")+sub('Application commentée',r"$E=5$ V, $U_0=2$ V, $R=10$ k$\Omega$, $C=100$ nF : $\tau=1$ ms et $u_C=5-3e^{-t/(1\,\mathrm{ms})}$. Le courant part de $0{,}30$ mA et tend vers zéro. À $t=\tau$, $u_C=3{,}896$ V.")+sub('Signes et charge initiale',r"Si $U_0>E$, le courant initial est négatif dans le sens choisi. Le condensateur rend une partie de son énergie au reste du circuit, tout en tendant vers la tension imposée. L’expression reste valable sans changer arbitrairement les flèches.")+box('methode','Contrôle dimensionnel',r"$RC$ a la dimension d’un temps puisque $\Omega\times\mathrm F=\mathrm s$. L’argument d’une exponentielle ne porte jamais d’unité."))
 c.c('Décharge libre et durée du transitoire',r'''Une capacité chargée à $U_0$ est isolée de sa source puis reliée à une résistance $R$. Avec le courant orienté comme dans le schéma RC, il est négatif pendant la décharge si $U_0>0$.
'''+box('loi','Évolution libre',r"$RC\dot u_C+u_C=0$, donc $u_C=U_0e^{-t/RC}$ et $i=-U_0e^{-t/RC}/R$. L’énergie stockée décroît comme $e^{-2t/RC}$.")+fig('charge','La courbe verte représente la tension de décharge normalisée.')+sub('Fixer une tolérance',r"Pour que $|u_C|/|U_0|\leq\varepsilon$, $t\geq\tau\ln(1/\varepsilon)$. On obtient $3\tau$ pour environ $5\,\%$, $4{,}605\tau$ pour $1\,\%$ et $6{,}908\tau$ pour $0{,}1\,\%$.")+box('piege','Préciser ce que l’on compare',r"Un seuil sur l’énergie n’est pas un seuil sur la tension : pour $\mathcal E/\mathcal E_0\leq\varepsilon$, il suffit de $t\geq(\tau/2)\ln(1/\varepsilon)$."))
 c.c('Le circuit RL et la bobine réelle',fig('rl','Ajouter la résistance interne r de la bobine à la résistance extérieure R.')+box('loi','Établissement du courant',r"$L\dot i+(R+r)i=E$. Poser $R_t=R+r$, $\tau=L/R_t$, $I_\infty=E/R_t$. Alors $i=I_\infty+(I_0-I_\infty)e^{-t/\tau}$. Pour $I_0=0$, $u_L=Ee^{-t/\tau}$.")+sub('La tension de la bobine réelle',r"Elle vaut $u_b=L\dot i+ri$. Sa valeur finale est $rI_\infty$, et non zéro. Seule la tension de l’inductance idéale s’annule en continu établi.")+fig('courants','RC et RL : un courant décroît pendant la charge d’une capacité, l’autre croît dans l’inductance.')+sub('Exemple',r"$E=6$ V, $R=90\ \Omega$, $r=10\ \Omega$, $L=100$ mH : $\tau=1$ ms, $I_\infty=60$ mA. À $\tau$, $i=37{,}9$ mA ; la bobine réelle tend vers $0{,}60$ V."))
 c.c('Régime libre d’une bobine',r'''Un courant $I_0$ circule dans une bobine. Après commutation, on lui offre une boucle de décharge résistive de résistance totale $R_t$. La source d’alimentation ne fait plus partie de cette boucle.
'''+box('loi','Restitution d’énergie',r"$L\dot i+R_ti=0$, donc $i=I_0e^{-t/\tau}$, $\tau=L/R_t$. L’énergie magnétique vaut $\mathcal E_L=(LI_0^2/2)e^{-2t/\tau}$ et $\dot{\mathcal E}_L=-R_ti^2$.")+sub('Pourquoi l’ouverture sans trajet est problématique',r"Le modèle $u=L\dot i$ associe une variation très rapide du courant à une forte tension. Lorsqu’un interrupteur ouvre une boucle inductive, les capacités parasites et les phénomènes d’arc peuvent devenir déterminants. On ne modélise pas cet état par $i(0^+)=0$ sans explication.")+box('methode','Dimensionner une décharge',r"Pour $L=50$ mH et $I_0=0{,}20$ A, la réserve est $1$ mJ. Avec $R_t=100\ \Omega$, $\tau=0{,}50$ ms ; le courant passe sous $1\,\%$ en $2{,}30$ ms. Augmenter $R_t$ accélère la décharge mais augmente $|u_L(0^+)|=R_tI_0$.")+sub('La continuité n’interdit pas un changement de pente',r"Le courant garde sa valeur initiale, mais sa dérivée change avec le schéma. La tension de la bobine peut donc subir un saut fini lors de la commutation."))
 c.c('Un circuit à deux mailles',r'''Une source idéale $E$ alimente un nœud $A$ par $R_1$. Entre $A$ et la masse sont branchés $R_2$ et un condensateur $C$. Sa tension est $u=V_A$.
'''+fig('rc-parallele','Le courant de la branche capacitive vaut C du/dt ; la loi des n?uds relie les trois branches.')+box('loi','Équation issue de la loi des nœuds',r"$(E-u)/R_1=u/R_2+C\dot u$. Donc $\tau\dot u+u=U_\infty$, avec $U_\infty=ER_2/(R_1+R_2)$ et $\tau=(R_1\parallel R_2)C$.")+sub('Un second raisonnement',r"Vu par le condensateur, le réseau résistif se remplace par son modèle de Thévenin : tension à vide $U_\infty$ et résistance $R_1\parallel R_2$ lorsque la source idéale est annulée. On retrouve un RC série, mais avec les paramètres équivalents.")+sub('Exemple',r"$E=9$ V, $R_1=3$ k$\Omega$, $R_2=6$ k$\Omega$, $C=1\ \mathrm{\mu F}$ et $u(0)=0$ donnent $u=6(1-e^{-t/(2\,\mathrm{ms})})$ V. Le courant de source ne tend pas vers zéro : $R_2$ continue à consommer.")+box('piege','La résistance vue par la réserve',r"La constante de temps ne vaut pas toujours $R_1C$. Il faut tenir compte de toutes les résistances qui permettent au condensateur d’échanger de la charge après la commutation."))
 c.c('Énergie d’une charge RC',r'''Pour un condensateur initialement déchargé, $u_C=E(1-e^{-t/\tau})$ et $i=(E/R)e^{-t/\tau}$. Multiplier l’équation de maille par le courant donne un bilan instantané.
'''+box('loi','Bilan de puissance puis d’énergie',r"$Ei=Ri^2+\dd(Cu_C^2/2)/\dd t$. De $0$ à $t$ : $W_G=CE^2(1-e^{-t/\tau})$ ; $W_J=(CE^2/2)(1-e^{-2t/\tau})$ ; $\mathcal E_C=(CE^2/2)(1-e^{-t/\tau})^2$. On vérifie $W_G=W_J+\mathcal E_C$.")+fig('energie','Le stockage et l’intégrale de dissipation tendent vers la même valeur lors d’une charge initialement nulle.')+sub('À la fin de la charge',r"La source a fourni $CE^2$ ; la moitié est stockée et la moitié dissipée. Cette répartition ne dépend pas de $R>0$, qui fixe la durée. La limite $R\to0$ est singulière pour le courant et ne décrit pas un circuit réel sans éléments parasites."))
 c.c('Énergie avec un état initial quelconque',box('loi','Un bilan plus général',r"Pour $u_C(0)=U_0$ et une source constante $E$, $W_G=CE(E-U_0)$, $W_J=\tfrac12C(E-U_0)^2$ et $\Delta\mathcal E_C=\tfrac12C(E^2-U_0^2)$. Leur relation est $W_G=W_J+\Delta\mathcal E_C$.")+sub('Démonstration courte',r"La charge nette reçue est $C(E-U_0)$ : la source fournit $E$ fois cette charge. L’intégration de $Ri^2$ utilise $i=(E-U_0)e^{-t/\tau}/R$ et $\int_0^\infty e^{-2t/\tau}\dd t=\tau/2$. L’identité énergétique résulte de $(E-U_0)^2+(E^2-U_0^2)=2E(E-U_0)$.")+sub('Une source peut recevoir de l’énergie',r"Pour $U_0=8$ V et $E=5$ V, avec $C=10\ \mathrm{\mu F}$ : $W_G=-150\ \mathrm{\mu J}$, $W_J=45\ \mathrm{\mu J}$, $\Delta\mathcal E_C=-195\ \mathrm{\mu J}$. La source idéale reçoit une partie de l’énergie rendue par la capacité.")+box('piege','Le RL alimenté en continu est différent',r"Après l’établissement du courant, la source RL continue à fournir une puissance Joule constante. L’énergie totale fournie de $0$ à $+\infty$ diverge ; on ne lui applique pas sans adaptation le bilan fini de la charge RC."))
 c.c('Lire et mesurer un temps caractéristique',box('loi','Trois méthodes complémentaires',r"1. Tangente à l’origine : elle rencontre l’asymptote finale à $t=\tau$.\par 2. Niveau : à $\tau$, le système a réalisé $1-e^{-1}\simeq63{,}2\,\%$ de sa variation totale.\par 3. Linéarisation : $\ln|s-s_\infty|=\ln|s_0-s_\infty|-t/\tau$. La pente vaut $-1/\tau$.")+fig('charge','Le niveau à utiliser est une fraction de la variation totale, pas nécessairement de la valeur finale.')+sub('Des incertitudes à la conclusion',r"Avec $\tau=RC$ et des grandeurs indépendantes, $u(\tau)/\tau=\sqrt{[u(R)/R]^2+[u(C)/C]^2}$. Pour une estimation par ajustement, tenir compte de l’incertitude sur le niveau final : les derniers points peuvent devenir très sensibles au bruit après logarithme.")+box('methode','Acquérir proprement',"Utiliser un échantillonnage nettement plus rapide que la constante de temps et une fenêtre couvrant plusieurs constantes. Vérifier que le demi-créneau est assez long et que la résistance de sortie du GBF est incluse dans le modèle."))
 c.c('Créneaux et réponses par morceaux',r'''Une excitation qui change de valeur impose une nouvelle solution particulière à chaque intervalle. La grandeur d’état est transmise continûment d’un intervalle au suivant.
'''+box('loi','Une propagation d’état',r"Sur une durée $\Delta$ où le niveau final est $S$, $s_{\rm fin}=S+(s_{\rm début}-S)e^{-\Delta/\tau}$. Cette relation suffit à construire plusieurs commutations sans résoudre à nouveau l’équation.")+sub('Créneau symétrique 0 / E',r"Poser $a=e^{-T/(2\tau)}$. En régime périodique, les valeurs minimale $u_-$ et maximale $u_+$ vérifient $u_+=E+(u_--E)a$ puis $u_-=a u_+$. Ainsi $u_+=E/(1+a)$ et $u_-=Ea/(1+a)$.")+sub('Interprétation',r"Si $T\gg\tau$, la capacité a le temps de se charger et se décharger presque complètement. Si $T\ll\tau$, l’ondulation est petite et la tension reste proche de $E/2$. Le régime périodique ne signifie pas que la tension est constante.")+box('piege','L’origine des temps est locale',r"Après une commutation à $t=t_1$, écrire l’exponentielle $e^{-(t-t_1)/\tau}$ et utiliser la valeur $s(t_1)$ comme condition initiale. Remettre implicitement $s$ à zéro change le problème."))
 c.tp_title='Acquérir un transitoire RC'
 c.tp=fig('rc','Inclure la résistance de sortie du GBF dans la résistance série totale.')+qs(r"Choisir $R\simeq10$ k$\Omega$ et $C\simeq100$ nF. Estimer $\tau$ puis régler un créneau dont le demi-palier dépasse $5\tau$.","Brancher les masses au même nœud. Observer simultanément l’entrée et la tension de capacité.",r"Mesurer $u_0,u_\infty$ et $\tau$ par le niveau à $63{,}2\,\%$ ; comparer à une tangente.","Ajuster l’expression exponentielle complète ; examiner les résidus et les intervalles exclus autour de la commutation.","Faire varier R puis C et vérifier les dépendances. Discuter tolérances, résistance du GBF et charge de l’oscilloscope.")+box('docu','Jeu simulé / Décharge de 5 V',r"$t$ (ms) : $0$, $0{,}5$, $1{,}0$, $1{,}5$, $2{,}0$, $3{,}0$.\par $u$ (V) : $5{,}00$, $3{,}03$, $1{,}84$, $1{,}12$, $0{,}68$, $0{,}25$.\par Ces données sont arrondies d’un modèle de constante $1$ ms ; elles ne sont pas une expérience réalisée.")+box('methode','Résultat attendu',"Donner une constante avec son incertitude, comparer au modèle et expliquer l’échelle des écarts. Une bonne exponentielle visuelle ne suffit pas à identifier les erreurs systématiques.")
 c.num_title='Euler pour une entrée quelconque'
 c.num=r'''Pour $\tau\dot u+u=e(t)$, Euler explicite donne $u_{n+1}=u_n+h(e_n-u_n)/\tau$. L’excitation ci-dessous est triangulaire ; elle n’est pas constante sur tout le calcul.
\begin{verbatim}
import numpy as np
tau, h = 1e-3, 1e-5
t = np.arange(0.0, 0.020 + h/2, h)
phase = (t % 0.004) / 0.004
e = 5.0 * (1.0 - np.abs(2.0*phase - 1.0))
u = np.zeros_like(t)
for n in range(len(t)-1):
    u[n+1] = u[n] + h*(e[n] - u[n])/tau
\end{verbatim}
'''+qs("Tracer l’entrée et la sortie avec leurs unités. Expliquer le retard de la réponse et l’arrondissement des sommets.",r"Remplacer l’entrée par un échelon constant de 5 V et comparer à $5(1-e^{-t/\tau})$.",r"Diviser $h$ par deux et comparer l’erreur. Pour la partie homogène, démontrer la condition $|1-h/\tau|<1$ de stabilité.",r"Essayer $h=1{,}5\tau$, puis $h>2\tau$ sur le régime libre : distinguer oscillation numérique et instabilité.")+box('piege','Stabilité et précision sont différentes',r"La condition $0<h<2\tau$ évite l’amplification du régime homogène discret. Une bonne précision et une décroissance sans oscillation artificielle demandent en pratique $h\ll\tau$. La durée la plus courte du forçage compte aussi.")
 c.synthesis=box('loi','Une équation, plusieurs réalisations',r"$\tau\dot s+s=S$ : $s=S+(s_0-S)e^{-t/\tau}$.\par RC série : $\tau=RC$ ; RL série : $\tau=L/R_t$.\par Un condensateur conserve $u_C$ ; une bobine conserve $i_L$ pour une commutation non impulsionnelle.\par Durée à $\varepsilon$ de l’écart initial : $t_\varepsilon=\tau\ln(1/\varepsilon)$.\par Euler : $s_{n+1}=s_n+h(S_n-s_n)/\tau$.")+sub('À démontrer sans solution',qs("La charge RC et le régime libre RL à partir des lois de circuit.","La réponse universelle avec une condition initiale quelconque.","Le bilan fini de la charge RC ; le bilan d’une décharge RL.","La constante de temps du condensateur placé dans un diviseur chargé."))+box('docu','Avant de rendre',r"\checkline{Le schéma est celui de l’intervalle étudié.}\checkline{La continuité porte sur la bonne grandeur.}\checkline{La solution vérifie l’équation et la limite finale.}\checkline{Le bilan d’énergie distingue stockage et dissipation.}")
 c.td_titles=['Identifier et résoudre','Charger une capacité','Décharger et chronométrer','Établir un courant','Changer le schéma','Faire le bilan','Mesurer et simuler','Explorer les limites']
 entries=[
 ('Identifier une constante',1,'8 min',qs(r"$2\times10^{-3}\dot u+u=6$, avec $u(0)=1$ V. Donner la constante de temps, la limite, la pente initiale et la solution."),r"$\tau=2$ ms ; $u_\infty=6$ V ; $\dot u(0)=2500$ V/s ; $u=6-5e^{-t/(2\,\mathrm{ms})}$. Les unités du coefficient de $\dot u$ sont des secondes."),
 ('Vérifier une solution',1,'10 min',qs(r"Une copie propose $u=E(1+e^{-t/\tau})$ pour la charge d’une capacité déchargée. Quels contrôles échouent ? Donner l’expression correcte."),r"La limite finale vaut bien E, mais $u(0)=2E$ au lieu de 0, et $\tau\dot u+u=E$ est néanmoins satisfaite. L’équation seule ne suffit pas : $u=E(1-e^{-t/\tau})$ satisfait aussi la condition initiale."),
 ('Une capacité déjà chargée',1,'12 min',qs(r"$R=5$ k$\Omega$, $C=2\ \mathrm{\mu F}$, $E=10$ V et $u_C(0)=4$ V. Donner $u_C(t)$ et $i(t)$ puis leurs valeurs à $t=\tau$."),r"$\tau=10$ ms ; $u_C=10-6e^{-t/\tau}$ V ; $i=1{,}2e^{-t/\tau}$ mA. À $\tau$, $u_C=7{,}793$ V et $i=0{,}441$ mA."),
 ('Atteindre un seuil',1,'10 min',qs(r"Un RC initialement déchargé reçoit $E=12$ V, avec $\tau=4$ ms. Quand atteint-il 9 V ?"),r"$9=12(1-e^{-t/\tau})$ donne $e^{-t/\tau}=1/4$ puis $t=\tau\ln4=5{,}545$ ms. Le logarithme porte sur un rapport sans dimension."),
 ('Une source plus faible',2,'12 min',qs(r"Une capacité initialement à 8 V est reliée à une source de 3 V par $R=10$ k$\Omega$, avec $C=1\ \mathrm{\mu F}$. Déterminer tension et courant. Le courant change-t-il de signe ?"),r"$\tau=10$ ms ; $u=3+5e^{-t/\tau}$ V ; $i=-0{,}5e^{-t/\tau}$ mA. Il reste négatif et tend vers zéro. La capacité fournit de la charge au circuit."),
 ('La résistance du GBF',2,'12 min',qs(r"Une source de Thévenin $E=5$ V, $r=50\ \Omega$ charge $C=100$ nF à travers $R=950\ \Omega$. Calculer $\tau$, la tension finale et le courant initial."),r"La capacité voit $R+r=1000\ \Omega$, donc $\tau=100\ \mathrm{\mu s}$. La tension finale est 5 V et le courant initial 5 mA si la capacité est déchargée. Oublier r sous-estimerait ici $\tau$ de 5 %."),
 ('Temps de demi-décharge',1,'10 min',qs(r"Un condensateur se décharge avec $\tau=3$ ms. Calculer le temps de demi-tension et le temps de demi-énergie."),r"$t_{u/2}=\tau\ln2=2{,}079$ ms. L’énergie décroît deux fois plus vite dans l’exponentielle : $t_{\mathcal E/2}=\tau\ln2/2=1{,}040$ ms."),
 ('Mesurer C par deux points',2,'15 min',qs(r"Une décharge à travers 20 k$\Omega$ passe de 4 V à 1 V en 12 ms. Déterminer $\tau$ puis $C$."),r"$u_2/u_1=e^{-\Delta t/\tau}$ : $\tau=12/\ln4=8{,}656$ ms ; $C=\tau/R=0{,}4328\ \mathrm{\mu F}$. La tension initiale absolue n’est pas nécessaire si la limite vaut zéro."),
 ('Changer de résistance',2,'12 min',qs(r"Une capacité $2\ \mathrm{\mu F}$ à 6 V se décharge sur 1 k$\Omega$ pendant 2 ms puis sur 4 k$\Omega$. Donner les deux expressions et la tension 8 ms après la seconde commutation."),r"Avant $t_1=2$ ms : $u=6e^{-t/(2\,\mathrm{ms})}$. À $t_1$, $u_1=6/e$. Après : $u=(6/e)e^{-(t-t_1)/(8\,\mathrm{ms})}$. Huit ms plus tard, $u=6/e^2=0{,}812$ V."),
 ('Une bobine au démarrage',1,'12 min',qs(r"$L=200$ mH, $R=80\ \Omega$, $r=20\ \Omega$, $E=10$ V, $i(0)=0$. Donner $\tau$, $i(t)$, $u_L(0^+)$ et la tension finale de la bobine réelle."),r"$\tau=2$ ms ; $i=0{,}10(1-e^{-t/\tau})$ A. $u_L(0^+)=10$ V. La tension finale de la bobine réelle est $ri_\infty=2$ V."),
 ('Un courant initial opposé',2,'12 min',qs(r"Une inductance idéale dans un circuit RL vérifie $\tau=5$ ms et $I_\infty=100$ mA, mais $i(0)=-50$ mA. Donner $i(t)$ et la date de passage par zéro."),r"$i=100-150e^{-t/\tau}$ mA. Le zéro vérifie $e^{-t/\tau}=2/3$, donc $t=\tau\ln(3/2)=2{,}027$ ms. La continuité n’impose pas que le courant garde toujours son signe initial."),
 ('Décharge magnétique',2,'12 min',qs(r"$L=50$ mH et $I_0=0{,}20$ A. La boucle de décharge a $R_t=100\ \Omega$. Donner $i(t)$, $u_L(0^+)$ et l’énergie dissipée totale."),r"$\tau=0{,}50$ ms ; $i=0{,}20e^{-t/\tau}$ A ; $u_L=-R_ti$ donc $u_L(0^+)=-20$ V. Toute l’énergie initiale $LI_0^2/2=1$ mJ devient chaleur."),
 ('Un diviseur avec C',2,'18 min',qs(r"Une source 12 V alimente $R_1=2$ k$\Omega$ puis le parallèle de $R_2=4$ k$\Omega$ et $C=3\ \mathrm{\mu F}$. La capacité est déchargée. Établir l’équation et résoudre."),r"$(12-u)/R_1=u/R_2+C\dot u$. $U_\infty=8$ V ; $R_1\parallel R_2=4/3$ k$\Omega$ ; $\tau=4$ ms. $u=8(1-e^{-t/\tau})$ V. Le courant de source tend vers 2 mA."),
 ('Une fuite de capacité',2,'15 min',qs(r"Une capacité $C=10\ \mathrm{\mu F}$ initialement à 5 V possède une résistance de fuite $R_f=1$ M$\Omega$. On branche un voltmètre $R_V=1$ M$\Omega$. Donner la constante de décharge et l’erreur d’une estimation de $R_f$ qui négligerait le voltmètre."),r"La résistance vue est $R_f\parallel R_V=0{,}50$ M$\Omega$ ; $\tau=5$ s. En attribuant cette décharge à la seule fuite, on estime $R_f=\tau/C=0{,}50$ M$\Omega$, soit une sous-estimation de 50 %."),
 ('Deux capacités en parallèle',2,'18 min',qs(r"Deux capacités identiques C sont chacune à $U_1$ et $U_2$. On les relie en parallèle, avec mêmes polarités, par une petite résistance. Donner la tension finale, l’énergie dissipée et sa valeur pour $C=1\ \mathrm{\mu F}$, $U_1=10$ V, $U_2=0$."),r"La charge totale se conserve : $U_f=(U_1+U_2)/2$. La perte est $C(U_1-U_2)^2/4=25\ \mathrm{\mu J}$. Le montage sans aucune résistance ni inductance ne décrit pas la redistribution physique."),
 ('Énergie de charge',1,'12 min',qs(r"Un condensateur de 10 $\mathrm{\mu F}$ est chargé de 0 à 6 V par une résistance. Donner l’énergie fournie par la source, l’énergie stockée et la dissipation."),r"$W_G=CE^2=360\ \mathrm{\mu J}$ ; $\mathcal E_C=180\ \mathrm{\mu J}$ ; $W_J=180\ \mathrm{\mu J}$. R détermine la durée mais pas ces valeurs pour le modèle annoncé."),
 ('Une charge non nulle',2,'15 min',qs(r"$C=2\ \mathrm{\mu F}$ passe de $U_0=8$ V à $E=5$ V. Calculer $W_G,W_J,\Delta\mathcal E_C$ et commenter."),r"$W_G=CE(E-U_0)=-30\ \mathrm{\mu J}$ ; $W_J=C(E-U_0)^2/2=9\ \mathrm{\mu J}$ ; $\Delta\mathcal E_C=-39\ \mathrm{\mu J}$. La source reçoit 30 $\mathrm{\mu J}$ tandis que 9 $\mathrm{\mu J}$ sont dissipés."),
 ('Énergie d’un RL',2,'18 min',qs(r"Un RL idéal de résistance totale R est alimenté par E avec $i(0)=0$. Exprimer l’énergie fournie entre 0 et t. Pourquoi son intégrale sur un temps infini diverge-t-elle ?"),r"$W_G=(E^2/R)[t-\tau(1-e^{-t/\tau})]$. À long terme, la puissance tend vers $E^2/R>0$ ; la source continue à alimenter la résistance. L’énergie magnétique tend seulement vers $LI_\infty^2/2$."),
 ('La pente d’un logarithme',2,'15 min',qs(r"Lors d’une décharge, la droite $\ln(u/1\,\mathrm V)=1{,}50-250t$, avec t en secondes, est ajustée. Donner $U_0,\tau$ et C si R = 8 k$\Omega$."),r"$U_0=e^{1{,}50}$ V = 4,482 V ; $\tau=1/250=4$ ms ; $C=0{,}50\ \mathrm{\mu F}$. Le logarithme doit porter sur une tension divisée par une référence de même unité."),
 ('Une incertitude sur RC',2,'12 min',qs(r"$R=10{,}0$ k$\Omega$, $u(R)=0{,}1$ k$\Omega$, $C=100$ nF, $u(C)=3$ nF ; mesures indépendantes. Donner $\tau$ et $u(\tau)$."),r"$\tau=1{,}00$ ms ; l’incertitude relative vaut $\sqrt{0{,}01^2+0{,}03^2}=0{,}03162$. Donc $u(\tau)=0{,}0316$ ms, à présenter par exemple comme $0{,}03$ ms."),
 ('Euler en trois pas',2,'15 min',qs(r"Pour une charge de 0 à E, appliquer Euler avec $h=\tau/2$. Donner $u_1,u_2,u_3$ en fractions de E et comparer $u_2$ à la solution exacte."),r"$u_{n+1}=u_n+(E-u_n)/2$ : $u_1=E/2$, $u_2=3E/4$, $u_3=7E/8$. À $t=\tau$, l’exact vaut $(1-e^{-1})E=0{,}6321E$ ; Euler donne $0{,}75E$, soit un écart $0{,}1179E$."),
 ('Un créneau périodique',3,'25 min',qs(r"Un RC reçoit un créneau 0/E de demi-période $\Delta=\tau$. En régime périodique, trouver $u_-$, $u_+$ et l’ondulation pour E = 6 V."),r"Avec $a=e^{-1}$ : $u_+=E/(1+a)=4{,}386$ V ; $u_-=Ea/(1+a)=1{,}614$ V ; ondulation $2{,}773$ V. Les deux relations de continuité sur un cycle fixent ces valeurs."),
 ('Un seuil de fermeture',3,'20 min',qs(r"Une capacité déchargée se charge vers E jusqu’au seuil $\alpha E$, puis se décharge jusqu’à $\beta E$ avec la même constante $\tau$, $0<\beta<\alpha<1$. Donner les deux durées et la période pour $\alpha=2/3$, $\beta=1/3$."),r"En régime établi : $t_c=\tau\ln[(1-\beta)/(1-\alpha)]$ et $t_d=\tau\ln(\alpha/\beta)$. Avec les seuils donnés, les deux durées valent $\tau\ln2$ et $T=2\tau\ln2$. La première charge depuis zéro est différente."),
 ('Un front de rampe',3,'25 min',qs(r"Un RC déchargé reçoit $e(t)=at$ pour $t\geq0$. Résoudre $\tau\dot u+u=at$ et vérifier la condition initiale. Interpréter à long terme."),r"Une particulière est $a(t-\tau)$. La solution est $u=a[t-\tau+\tau e^{-t/\tau}]$. À t = 0, u et sa pente sont nuls. À long terme $u\simeq a(t-\tau)$ : l’écart à l’entrée tend vers $a\tau$, sans régime permanent constant.")]
 for e in entries:c.e(*e)
 c.d('Une capacité entre deux branches',r"Une capacité C est en parallèle avec $R_2$, le tout alimenté par E à travers $R_1$. Avant $t=0$, elle est déchargée. À $t=t_1$, on annule la source idéale en la remplaçant par un fil, sans changer les résistances."+qs(r"Établir la phase de charge et les courants de chaque branche.",r"Donner la phase libre après $t_1$ ; expliquer pourquoi la constante de temps reste identique.",r"Calculer la charge totale rendue dans la phase libre et sa répartition entre les résistances.",r"Application : $E=9$ V, $R_1=3$ k$\Omega$, $R_2=6$ k$\Omega$, $C=1\ \mathrm{\mu F}$, $t_1=2$ ms."),"1. La loi des nœuds donne une équation à une inconnue u. 2. Lors de la décharge, les deux résistances relient la même paire de nœuds. 3. Intégrer u/Rj sur le temps.",r'''$U_\infty=6$ V et $\tau=(R_1\parallel R_2)C=2$ ms. Pendant la charge, $u=U_\infty(1-e^{-t/\tau})$, $i_1=(E-u)/R_1$, $i_2=u/R_2$ et $i_C=C\dot u$.
À $t_1$, $U_1=6(1-e^{-1})=3{,}793$ V. Pour $t>t_1$, $u=U_1e^{-(t-t_1)/\tau}$. La résistance vue par C demeure $R_1\parallel R_2$ car la source annulée est un fil.
La charge totale quittant l’armature positive vaut $CU_1=3{,}793\ \mathrm{\mu C}$. Dans la branche $R_j$, sa valeur est $\int u/R_j\dd t=U_1\tau/R_j$. Les fractions valent $R_2/(R_1+R_2)=2/3$ dans $R_1$ et $1/3$ dans $R_2$ : $2{,}528$ et $1{,}264\ \mathrm{\mu C}$.
'''+box('methode','Vérifier le résultat',r"Les charges de branche se somment à $CU_1$. Les dissipations correspondantes se somment à $CU_1^2/2$ ; la plus faible résistance dissipe la plus grande part pendant cette décharge parallèle."))
 c.d('Protéger une bobine sans trop ralentir',r"Une inductance L porte $I_0$ puis se décharge sur une résistance totale $R_d$. On impose une tension initiale de module au plus $U_{\max}$ et un courant au plus égal à $\varepsilon I_0$ après un temps $t_s$."+qs(r"Traduire les deux contraintes en bornes sur $R_d$.",r"Donner une condition de faisabilité.",r"Calculer l’intervalle pour $L=50$ mH, $I_0=0{,}20$ A, $U_{\max}=30$ V, $\varepsilon=0{,}01$, $t_s=2$ ms.","Choisir une valeur, calculer sa constante et vérifier l’énergie à dissiper."),"1. La tension initiale vaut -Rd I0. 2. Utiliser l’exponentielle de courant et prendre le logarithme. 3. Ne pas mélanger le seuil sur le courant et le seuil sur l’énergie.",r'''La limite de tension impose $R_d\leq U_{\max}/I_0$. La contrainte de courant impose $I_0e^{-R_dt_s/L}\leq\varepsilon I_0$, donc
\[\frac{L\ln(1/\varepsilon)}{t_s}\leq R_d\leq\frac{U_{\max}}{I_0}.\]
Le montage est réalisable si la borne basse ne dépasse pas la borne haute. Les valeurs numériques donnent $115{,}13\ \Omega\leq R_d\leq150\ \Omega$. Choisir $R_d=125\ \Omega$ : $\tau=0{,}40$ ms, $|u_L(0)|=25$ V et $i(2\,\mathrm{ms})/I_0=e^{-5}=0{,}00674$.
Toute l’énergie $LI_0^2/2=1$ mJ doit être dissipée. La puissance initiale est $R_dI_0^2=5$ W, puis elle décroît comme $e^{-2t/\tau}$ : la tenue impulsionnelle de la résistance compte autant que sa puissance moyenne.
''')
 c.d('Retrouver une entrée et tester Euler',qs(r"On désire $u(t)=U(1-e^{-t/a})^2$ sur un RC de constante $\tau$. Retrouver l’entrée $e=\tau\dot u+u$.",r"Dans le cas $a=\tau$, simplifier e et comparer ses limites à celles de u.",r"Proposer un test numérique d’Euler sur cette entrée avec une solution exacte connue.",r"Pour le régime homogène, discuter les cas $h/\tau<1$, $1<h/\tau<2$ et $h/\tau>2$."),"1. Dériver le carré avant de développer. 2. Utiliser z = exp(-t/τ). 3. La différence de deux solutions numériques suit un facteur 1-h/τ à chaque pas.",r'''$\dot u=(2U/a)e^{-t/a}(1-e^{-t/a})$, donc
\[e=U(1-e^{-t/a})^2+\frac{2U\tau}{a}e^{-t/a}(1-e^{-t/a}).\]
Si $a=\tau$, l’entrée se réduit à $e=U(1-e^{-2t/\tau})$. Elle part de zéro et tend vers U ; la sortie part avec une pente nulle. Alimenter Euler avec les valeurs exactes de cette entrée et comparer sa sortie à la formule proposée, puis diviser h par deux.
La partie homogène obéit à $z_{n+1}=(1-h/\tau)z_n$. Pour $0<h/\tau<1$, elle décroît sans alternance ; pour $1<h/\tau<2$, elle alterne en décroissant ; au-delà de 2, son module croît. À $h=2\tau$, le module reste constant : ce n’est pas une décroissance correcte. Ce test analyse l’algorithme et non un phénomène d’oscillation du RC.
''')
 c.dm_title='Une temporisation avec fuite'
 c.dm=r"Une source idéale $E=12$ V alimente une résistance $R=100$ k$\Omega$, suivie du parallèle d’une capacité $C=10\ \mathrm{\mu F}$ et d’une fuite $R_f=300$ k$\Omega$. La capacité est déchargée."+qs(r"Faire le schéma orienté et écrire l’équation de nœud. \textbf{4 points}",r"Déterminer la tension finale et la constante de temps. \textbf{4 points}",r"Résoudre et calculer la date où u atteint 6 V. \textbf{4 points}",r"Un voltmètre de 1 M$\Omega$ est branché sur C. Donner les nouveaux paramètres et la nouvelle date du seuil. \textbf{4 points}",r"Proposer un protocole de mesure de C puis citer deux sources d’erreur à considérer. \textbf{4 points}")
 c.dm_sol=sub('1 / 4 points',r"Avec u orientée vers le nœud haut de C, $(E-u)/R=u/R_f+C\dot u$. Le schéma orienté vaut 2 points ; le bilan et les relations des dipôles 2.")+sub('2 et 3 / 8 points',r"$U_\infty=ER_f/(R+R_f)=9$ V ; $\tau=(R\parallel R_f)C=0{,}75$ s (4). $u=9(1-e^{-t/0{,}75})$ et $u=6$ V à $t=0{,}75\ln3=0{,}824$ s (4). Le seuil est accessible car il est inférieur à 9 V.")+sub('4 / 4 points',r"$R_f\parallel R_V=230{,}769$ k$\Omega$ ; $U'_\infty=8{,}372$ V ; $\tau'=0{,}6977$ s. $t'=-\tau'\ln(1-6/U'_\infty)=0{,}880$ s. Le chargement du voltmètre retarde ici le seuil malgré une constante de temps plus petite.")+sub('5 / 4 points',r"Mesurer la courbe, ajuster séparément la limite et la constante, puis calculer $C=\tau/R_{\rm vu}$ (2). Discuter fuite, entrée du voltmètre, tolérances et résolution temporelle (deux limites expliquées : 2).")
 c.ds_title='Des capacités aux inductances'
 c.ds=[sub('A / Charge RC / 8 points',r"$E=10$ V, $R=4$ k$\Omega$, $C=500$ nF ; la capacité est initialement à $U_0=2$ V.")+qs(r"Établir l’équation, annoncer la condition initiale et la constante de temps. \textbf{3 points}",r"Donner tension et courant en fonction du temps. \textbf{2 points}",r"Calculer le temps où u = 8 V. \textbf{1 point}",r"Calculer l’énergie fournie, dissipée et stockée en variation sur l’évolution complète. \textbf{2 points}")+sub('B / Établissement RL / 6 points',r"Une bobine $L=100$ mH, $r=10\ \Omega$ est en série avec $R=90\ \Omega$, sous $E=6$ V. Le courant initial est nul.")+qs(r"Établir l’équation et résoudre. \textbf{3 points}",r"Donner le courant final, la tension finale de la bobine réelle et son énergie stockée. \textbf{3 points}"),sub('C / Décharge et calcul numérique / 6 points',r"Après établissement du courant précédent, on isole la source et on décharge la bobine dans une boucle de résistance totale $R_d=200\ \Omega$.")+qs(r"Donner la nouvelle constante, l’expression du courant et la tension initiale de l’inductance idéale. \textbf{2 points}",r"Quand le courant atteint-il $1\,\%$ de sa valeur initiale ? \textbf{1 point}",r"Écrire le schéma d’Euler de ce régime libre et donner la condition de stabilité. \textbf{2 points}",r"Expliquer pourquoi un courant numérique qui alterne de signe peut révéler un pas trop grand. \textbf{1 point}")]
 c.ds_sol=[sub('A / 8 points',r"$RC\dot u+u=E$, $u(0)=2$ V et $\tau=2$ ms (3). $u=10-8e^{-t/\tau}$ V ; $i=2e^{-t/\tau}$ mA (2). Pour 8 V, $t=\tau\ln4=2{,}773$ ms (1). $W_G=40\ \mathrm{\mu J}$ ; $W_J=16\ \mathrm{\mu J}$ ; $\Delta\mathcal E_C=24\ \mathrm{\mu J}$ (2).")+sub('B / 6 points',r"$L\dot i+100i=6$ ; $\tau=1$ ms ; $i=0{,}060(1-e^{-t/\tau})$ A (3). $I_\infty=60$ mA ; $u_b(\infty)=0{,}60$ V ; $\mathcal E_L=180\ \mathrm{\mu J}$ (3)."),sub('C / 6 points',r"$\tau_d=L/R_d=0{,}50$ ms ; $i=0{,}060e^{-t/\tau_d}$ A ; $u_L(0)=-12$ V (2). Le seuil est atteint à $\tau_d\ln100=2{,}303$ ms (1). Euler : $i_{n+1}=(1-h/\tau_d)i_n$ ; stabilité asymptotique pour $0<h<2\tau_d$ (2). Si $h>\tau_d$, le facteur change de signe, contrairement à la décharge exacte : il s’agit d’un artefact du calcul (1).")+box('methode','Vérifier la correction',"Pour A, l’énergie de source est égale à la somme des deux autres. Pour B, ne pas annuler la résistance interne de la bobine. Pour C, utiliser la résistance de la nouvelle boucle, pas celle de la charge initiale.")]
 c.hints="E05 : conserver les flèches malgré le courant négatif. E09 : transmettre la tension à la commutation. E13 : utiliser la loi des nœuds. E15 : conserver la charge totale puis comparer les énergies. E24 : chercher une solution particulière affine."
 c.eval_hints="Dans le DM, la limite finale et la constante changent toutes les deux lorsque le voltmètre est branché. Dans le DS, séparer la charge et la décharge de la bobine, avec deux schémas et deux constantes."
 c.source('DM réel / Charge très rapide','https://mpsi.schleck.ovh/fichiers/devoirs/2025-2026/dm3_elec.pdf','MPSI, schleck.ovh ; DM3 à rendre le 5 novembre 2025 ; exercice 2, questions 1 à 5, page 2/3.',"Prévoir 20 minutes. Travailler seulement la première phase de charge sur le schéma original. La phase suivante comporte deux capacités et relève du deuxième ordre.",r"Lors de la charge en position A, $rC_1\dot u_1+u_1=E$ et $u_1(0)=0$. Donc $u_1=E(1-e^{-t/(rC_1)})$. Avec $r=10\ \Omega$ et $C_1=30$ nF, $\tau=0{,}30\ \mathrm{\mu s}$. Atteindre $99{,}9\,\%$ demande $t_1=\tau\ln1000=2{,}072\ \mathrm{\mu s}$. À 1 ms, $u_1$ est pratiquement égal à 15 V dans ce modèle.")
 c.source('DS réel / Une bobine au démarrage','https://mpsi.schleck.ovh/fichiers/devoirs/2025-2026/ds3_elec_chimie.pdf','MPSI, schleck.ovh ; DS3 du 13 novembre 2025 ; exercice 2, partie I, questions 1 à 6, page 2/4.',"Prévoir 25 minutes. Établir le courant dans la bobine réelle et différencier la tension inductive de la tension totale. On peut ensuite lire les questions 7 et 8 sur l’ouverture du circuit.",r"$L\dot i+(R+r)i=E$, $\tau=L/(R+r)$ ; si le courant initial est nul, $i=E(1-e^{-t/\tau})/(R+r)$. Au régime final, $I_0=E/(R+r)$, $U_0=rI_0$, $\mathcal E_L=LI_0^2/2$ et $P_{J,b}=rI_0^2$. L’ouverture sans trajet de décharge tend à produire une forte tension : elle ne justifie pas un saut instantané du courant dans le modèle de bobine idéale.")
 c.next="Le chapitre 04 introduit le stockage dans deux réserves et l’échange périodique d’énergie : c’est l’oscillateur harmonique, mécanique ou électrique."
 for name,a,b,t in [('E03-u',10-6/exp(1),7.79272335297,1e-9),('E04-seuil',.004*log(4),.00554517744448,1e-12),('E08-C',.012/log(4)/20000,4.32808512267e-7,1e-16),('E09-u',6/exp(2),.81201169942,1e-10),('E11-zéro',.005*log(1.5),.00202732554054,1e-12),('E13-tau',2000*4000/6000*3e-6,.004,1e-12),('E15-perte',1e-6*100/4,25e-6,1e-12),('E20-u',.001*sqrt(.01**2+.03**2),.0000316227766017,1e-15),('E22-max',6/(1+exp(-1)),4.38635147178,1e-10),('D2-Rmin',.05*log(100)/.002,115.1292546497,1e-9),('DM-tseuil',.75*log(3),.823959216501,1e-10),('DM-chargé-t',-(1/(1/1e5+1/3e5+1/1e6))*1e-5*log(1-6/(12*(1/(1/3e5+1/1e6))/(1e5+1/(1/3e5+1/1e6)))),.880,0.001),('DS-WG',5e-7*10*8,40e-6,1e-12),('R1-tau',10*30e-9,3e-7,1e-12)]:c.check(name,a,b,t)
 return c
